import SwiftUI

public struct ManicatCommandItem: Identifiable {
    public let id: String
    public let label: String
    public let description: String?
    public let group: String?
    public let keywords: [String]
    public let shortcut: String?

    public init(id: String, label: String, description: String? = nil, group: String? = nil, keywords: [String] = [], shortcut: String? = nil) {
        self.id = id
        self.label = label
        self.description = description
        self.group = group
        self.keywords = keywords
        self.shortcut = shortcut
    }
}

/// Mirrors command-palette.tsx / command-palette.rn.tsx / command-palette.vue: a search field over grouped, filtered commands. The
/// arrow keys move, Return selects and Escape calls `onClose`.
public struct ManicatCommandPalette: View {
    public struct Styles {
        public var input: ManicatStyle = { $0 }
        public var list: ManicatStyle = { $0 }
        public var group: ManicatStyle = { $0 }
        public var item: ManicatStyle = { $0 }
        public var itemText: ManicatStyle = { $0 }
        public var empty: ManicatStyle = { $0 }
        public init() {}
    }

    @Environment(\.manicat) private var tokens
    @FocusState private var focused: Bool
    @State private var query = ""
    @State private var active = 0

    private let items: [ManicatCommandItem]
    private let placeholder: String
    private let label: String
    private let autoFocus: Bool
    private let onSelect: (ManicatCommandItem) -> Void
    private let onClose: (() -> Void)?
    private let styles: Styles

    public init(items: [ManicatCommandItem], placeholder: String = "Search commands", label: String = "Command palette", autoFocus: Bool = false, styles: Styles = Styles(), onClose: (() -> Void)? = nil, onSelect: @escaping (ManicatCommandItem) -> Void) {
        self.items = items
        self.placeholder = placeholder
        self.label = label
        self.autoFocus = autoFocus
        self.styles = styles
        self.onClose = onClose
        self.onSelect = onSelect
    }

    private var results: [ManicatCommandItem] {
        let needle = query.trimmingCharacters(in: .whitespaces).lowercased()
        if needle.isEmpty { return items }
        return items.filter { item in ([item.label, item.description ?? "", item.group ?? ""] + item.keywords).contains { $0.lowercased().contains(needle) } }
    }

    public var body: some View {
        let shown = results

        VStack(spacing: 0) {
            field(shown)
            list(shown)
        }
        .background(tokens.surface, in: RoundedRectangle(cornerRadius: 26))
        .overlay(RoundedRectangle(cornerRadius: 26).stroke(tokens.border, lineWidth: 1))
        .accessibilityElement(children: .contain)
        .accessibilityLabel(label)
        .onAppear { if autoFocus { focused = true } }
    }

    private func field(_ shown: [ManicatCommandItem]) -> some View {
        TextField("", text: $query, prompt: Text(placeholder).foregroundColor(tokens.textMuted))
            .textFieldStyle(.plain)
            .focused($focused)
            .font(.system(size: ManicatMetrics.textSm))
            .foregroundStyle(tokens.foreground)
            .padding(.horizontal, ManicatMetrics.space.s4)
            .frame(minHeight: ManicatMetrics.controlHeight.md)
            .overlay(alignment: .bottom) { Rectangle().fill(tokens.border).frame(height: 1) }
            .onChange(of: query) { _, _ in active = 0 }
            .onSubmit { if shown.indices.contains(active) { onSelect(shown[active]) } }
            .onKeyPress(.downArrow) { move(1, count: shown.count); return .handled }
            .onKeyPress(.upArrow) { move(-1, count: shown.count); return .handled }
            .onKeyPress(.escape) { onClose?(); return .handled }
            .accessibilityLabel(placeholder)
            .manicatStyle(styles.input)
    }

    private func list(_ shown: [ManicatCommandItem]) -> some View {
        var groups: [String] = []
        for item in shown where !groups.contains(item.group ?? "") { groups.append(item.group ?? "") }

        return ScrollView {
            VStack(alignment: .leading, spacing: 0) {
                if shown.isEmpty {
                    Text("No results").font(.system(size: ManicatMetrics.textSm)).foregroundStyle(tokens.textMuted).padding(ManicatMetrics.space.s3).manicatStyle(styles.empty)
                }
                ForEach(groups, id: \.self) { group in
                    section(group, shown)
                }
            }
            .padding(6)
        }
        .frame(maxHeight: 320)
        .manicatStyle(styles.list)
    }

    @ViewBuilder private func section(_ group: String, _ shown: [ManicatCommandItem]) -> some View {
        if !group.isEmpty {
            Text(group)
                .font(.system(size: ManicatMetrics.textXs, weight: .medium))
                .foregroundStyle(tokens.textMuted)
                .padding(.horizontal, ManicatMetrics.space.s3)
                .padding(.top, ManicatMetrics.space.s3)
                .padding(.bottom, 4)
                .manicatStyle(styles.group)
        }
        ForEach(shown.filter { ($0.group ?? "") == group }) { item in
            row(item, index: shown.firstIndex { $0.id == item.id } ?? 0)
        }
    }

    private func row(_ item: ManicatCommandItem, index: Int) -> some View {
        Button { onSelect(item) } label: {
            HStack(spacing: ManicatMetrics.space.s3) {
                VStack(alignment: .leading, spacing: 0) {
                    Text(item.label).font(.system(size: ManicatMetrics.textSm)).foregroundStyle(tokens.foreground).manicatStyle(styles.itemText)
                    if let description = item.description {
                        Text(description).font(.system(size: ManicatMetrics.textXs)).foregroundStyle(tokens.textMuted)
                    }
                }
                Spacer(minLength: 0)
                if let shortcut = item.shortcut { Text(shortcut).font(.system(size: ManicatMetrics.textXs)).foregroundStyle(tokens.textMuted) }
            }
            .padding(.horizontal, ManicatMetrics.space.s3)
            .frame(minHeight: ManicatMetrics.controlHeight.md)
            .background(index == active ? tokens.surfaceMuted : .clear, in: RoundedRectangle(cornerRadius: ManicatMetrics.radiusControl - 4))
            .contentShape(Rectangle())
            .manicatStyle(styles.item)
        }
        .buttonStyle(.plain)
        .onHover { inside in if inside { active = index } }
    }

    private func move(_ step: Int, count: Int) {
        guard count > 0 else { return }
        active = (active + step + count) % count
    }
}

import SwiftUI

/// The Manicat UI design tokens as SwiftUI values. Same names and meaning as registry/foundation.css and lib/rn-tokens.ts.
/// `scripts/check-parity.mjs` compares every colour below with rn-tokens.ts, so the three never drift.
public struct ManicatTokens {
    public let background, surface, surfaceMuted, foreground, textSecondary, textMuted, border, borderStrong: Color
    public let accent, accentStrong, accentSubtle, success, warning, danger: Color
    public let controlOn, controlTrack, controlThumb, controlThumbOn: Color
    /// Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4.
    public let series: [Color]

    public static let light = ManicatTokens(
        background: Color(hex: "#ffffff"), surface: Color(hex: "#ffffff"), surfaceMuted: Color(hex: "#f6f6f6"),
        foreground: Color(hex: "#1b1b1b"), textSecondary: Color(hex: "#6e6e6e"), textMuted: Color(hex: "#8f8f8f"),
        border: Color(hex: "#ebebeb"), borderStrong: Color(hex: "#c9c9c9"),
        accent: Color(hex: "#4a4a4a"), accentStrong: Color(hex: "#303030"), accentSubtle: Color(hex: "#4a4a4a", opacity: 0.1),
        success: Color(hex: "#1f8a4c"), warning: Color(hex: "#b8741a"), danger: Color(hex: "#d03b3b"),
        controlOn: Color(hex: "#2c2c2c"), controlTrack: Color(hex: "#e2e2e2"), controlThumb: Color(hex: "#ffffff"), controlThumbOn: Color(hex: "#ffffff"),
        series: [Color(hex: "#1f7dcf"), Color(hex: "#7128a5"), Color(hex: "#e58f00"), Color(hex: "#009e84")]
    )

    public static let dark = ManicatTokens(
        background: Color(hex: "#2b2b2b"), surface: Color(hex: "#303030"), surfaceMuted: Color(hex: "#3c3c3c"),
        foreground: Color(hex: "#f1f1f1"), textSecondary: Color(hex: "#c4c4c4"), textMuted: Color(hex: "#a0a0a0"),
        border: Color(hex: "#454545"), borderStrong: Color(hex: "#5c5c5c"),
        accent: Color(hex: "#cfcfcf"), accentStrong: Color(hex: "#e6e6e6"), accentSubtle: Color(hex: "#cfcfcf", opacity: 0.13),
        success: Color(hex: "#5fd48a"), warning: Color(hex: "#f0b95c"), danger: Color(hex: "#ff8a80"),
        controlOn: Color(hex: "#ececec"), controlTrack: Color(hex: "#515151"), controlThumb: Color(hex: "#f4f4f4"), controlThumbOn: Color(hex: "#2b2b2b"),
        series: [Color(hex: "#55adff"), Color(hex: "#9c37be"), Color(hex: "#e66e00"), Color(hex: "#00a861")]
    )
}

/// Shape and rhythm shared by every component, in points.
public enum ManicatMetrics {
    public static let radiusControl: CGFloat = 18
    public static let radiusPill: CGFloat = 9999
    public static let controlHeight: (sm: CGFloat, md: CGFloat, lg: CGFloat) = (36, 44, 50)
    public static let space: (s1: CGFloat, s2: CGFloat, s3: CGFloat, s4: CGFloat, s5: CGFloat) = (4, 8, 12, 16, 20)
    public static let textXs: CGFloat = 12
    public static let textSm: CGFloat = 14
    public static let textLg: CGFloat = 18
}

/// Restyles one named part of a component. The counterpart of an entry of `classNames` on the web and of `styles` on React Native:
/// every component has a `Styles` struct with one of these per part, and applies it to that part.
public typealias ManicatStyle = (AnyView) -> AnyView

public extension View {
    /// Applies a `ManicatStyle` to this view.
    func manicatStyle(_ style: ManicatStyle) -> some View { style(AnyView(self)) }
}

/// Lays children out in rows that wrap, like flex-wrap on the web. Used by chips, tags, breadcrumbs and anything else that flows.
public struct ManicatFlowLayout: Layout {
    public var spacing: CGFloat
    public var lineSpacing: CGFloat

    public init(spacing: CGFloat = 8, lineSpacing: CGFloat = 8) {
        self.spacing = spacing
        self.lineSpacing = lineSpacing
    }

    public func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        arrange(width: proposal.width ?? .infinity, subviews: subviews).size
    }

    public func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let result = arrange(width: bounds.width, subviews: subviews)
        for (index, origin) in result.origins.enumerated() {
            subviews[index].place(at: CGPoint(x: bounds.minX + origin.x, y: bounds.minY + origin.y), proposal: .unspecified)
        }
    }

    private func arrange(width: CGFloat, subviews: Subviews) -> (size: CGSize, origins: [CGPoint]) {
        var origins: [CGPoint] = []
        var x: CGFloat = 0, y: CGFloat = 0, rowHeight: CGFloat = 0, widest: CGFloat = 0
        for subview in subviews {
            let size = subview.sizeThatFits(.unspecified)
            if x > 0, x + size.width > width {
                x = 0
                y += rowHeight + lineSpacing
                rowHeight = 0
            }
            origins.append(CGPoint(x: x, y: y))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
            widest = max(widest, x - spacing)
        }
        return (CGSize(width: widest, height: y + rowHeight), origins)
    }
}

private struct ManicatTokensKey: EnvironmentKey {
    static let defaultValue = ManicatTokens.light
}

public extension EnvironmentValues {
    /// The tokens for the current colour scheme. Read them with `@Environment(\.manicat)`.
    var manicat: ManicatTokens {
        get { colorScheme == .dark ? .dark : self[ManicatTokensKey.self] }
        set { self[ManicatTokensKey.self] = newValue }
    }
}

public extension Color {
    init(hex: String, opacity: Double = 1) {
        let digits = hex.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
        var value: UInt64 = 0
        Scanner(string: digits).scanHexInt64(&value)
        self.init(.sRGB, red: Double((value >> 16) & 0xff) / 255, green: Double((value >> 8) & 0xff) / 255, blue: Double(value & 0xff) / 255, opacity: opacity)
    }
}
